-- BECE ICT Questions - 2024 (40 questions)
INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Computer Fundamentals (Questions 1-10)
('q_bece_ict_2024_001', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is an example of an input device?', 'multiple_choice', '["A. Monitor", "B. Printer", "C. Keyboard", "D. Speaker"]', 'C', 'A keyboard is an input device used to enter data into a computer. Monitors, printers, and speakers are output devices.', 'easy', 1, 1),
('q_bece_ict_2024_002', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'CPU stands for:', 'multiple_choice', '["A. Central Processing Unit", "B. Computer Personal Unit", "C. Central Personal Unit", "D. Computer Processing Unit"]', 'A', 'CPU stands for Central Processing Unit. It is the brain of the computer that processes instructions and data.', 'easy', 1, 2),
('q_bece_ict_2024_003', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is NOT a type of computer?', 'multiple_choice', '["A. Desktop", "B. Laptop", "C. Smartphone", "D. Calculator"]', 'D', 'A calculator is an electronic device but not a computer. Desktops, laptops, and smartphones are all types of computers.', 'easy', 1, 3),
('q_bece_ict_2024_004', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'RAM stands for:', 'multiple_choice', '["A. Read Access Memory", "B. Random Access Memory", "C. Ready Access Memory", "D. Rapid Access Memory"]', 'B', 'RAM stands for Random Access Memory. It is the temporary memory that stores data being actively used by the computer.', 'easy', 1, 4),
('q_bece_ict_2024_005', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which device is used to connect a computer to the internet?', 'multiple_choice', '["A. Monitor", "B. Modem", "C. Mouse", "D. Microphone"]', 'B', 'A modem (modulator-demodulator) is used to connect a computer to the internet by converting digital signals to analog and vice versa.', 'medium', 1, 5),
('q_bece_ict_2024_006', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'The brain of the computer is called:', 'multiple_choice', '["A. Memory", "B. Hard disk", "C. Processor", "D. Keyboard"]', 'C', 'The processor (CPU) is called the brain of the computer because it carries out all the processing and calculations.', 'easy', 1, 6),
('q_bece_ict_2024_007', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is an output device?', 'multiple_choice', '["A. Scanner", "B. Webcam", "C. Joystick", "D. Printer"]', 'D', 'A printer is an output device that produces hard copies of documents. Scanner, webcam, and joystick are input devices.', 'easy', 1, 7),
('q_bece_ict_2024_008', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'The smallest unit of data in a computer is:', 'multiple_choice', '["A. Byte", "B. Bit", "C. Kilobyte", "D. Megabyte"]', 'B', 'A bit (binary digit) is the smallest unit of data in computing. It can have a value of either 0 or 1.', 'medium', 1, 8),
('q_bece_ict_2024_009', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'How many bits make a byte?', 'multiple_choice', '["A. 2", "B. 4", "C. 8", "D. 16"]', 'C', '8 bits make up 1 byte. A byte is the basic unit for measuring digital information storage.', 'easy', 1, 9),
('q_bece_ict_2024_010', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which type of memory loses its contents when power is turned off?', 'multiple_choice', '["A. ROM", "B. RAM", "C. Hard disk", "D. CD-ROM"]', 'B', 'RAM is volatile memory, meaning it loses all stored data when the computer is turned off. ROM, hard disk, and CD-ROM retain data.', 'medium', 1, 10),

-- Software and Operating Systems (Questions 11-20)
('q_bece_ict_2024_011', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is an operating system?', 'multiple_choice', '["A. Microsoft Word", "B. Windows", "C. Chrome", "D. Excel"]', 'B', 'Windows is an operating system. Microsoft Word and Excel are application software, and Chrome is a web browser.', 'easy', 1, 11),
('q_bece_ict_2024_012', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Software that is free to use and distribute is called:', 'multiple_choice', '["A. Freeware", "B. Hardware", "C. Firmware", "D. Malware"]', 'A', 'Freeware is software that is distributed free of charge. Users can use and share it without paying.', 'medium', 1, 12),
('q_bece_ict_2024_013', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Microsoft Word is an example of:', 'multiple_choice', '["A. Operating system", "B. Word processing software", "C. Spreadsheet software", "D. Database software"]', 'B', 'Microsoft Word is word processing software used for creating and editing text documents.', 'easy', 1, 13),
('q_bece_ict_2024_014', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which software would you use to create a budget spreadsheet?', 'multiple_choice', '["A. Microsoft Word", "B. Microsoft Excel", "C. Microsoft PowerPoint", "D. Microsoft Paint"]', 'B', 'Microsoft Excel is spreadsheet software ideal for creating budgets, performing calculations, and organizing data in rows and columns.', 'easy', 1, 14),
('q_bece_ict_2024_015', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'The main function of an operating system is to:', 'multiple_choice', '["A. Create documents", "B. Browse the internet", "C. Manage computer resources", "D. Play games"]', 'C', 'The main function of an operating system is to manage computer hardware and software resources and provide services for application programs.', 'medium', 1, 15),
('q_bece_ict_2024_016', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which file extension is associated with Microsoft Word documents?', 'multiple_choice', '["A. .xlsx", "B. .pptx", "C. .docx", "D. .pdf"]', 'C', 'The .docx extension is used for Microsoft Word documents. .xlsx is for Excel, .pptx is for PowerPoint, and .pdf is for PDF documents.', 'medium', 1, 16),
('q_bece_ict_2024_017', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'A set of instructions that tells the computer what to do is called:', 'multiple_choice', '["A. Hardware", "B. Software", "C. Monitor", "D. Keyboard"]', 'B', 'Software is a set of instructions (programs) that tell the computer hardware what to do and how to do it.', 'easy', 1, 17),
('q_bece_ict_2024_018', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is presentation software?', 'multiple_choice', '["A. Notepad", "B. Calculator", "C. PowerPoint", "D. Paint"]', 'C', 'PowerPoint is presentation software used to create slideshows and visual presentations.', 'easy', 1, 18),
('q_bece_ict_2024_019', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'The desktop icons represent:', 'multiple_choice', '["A. Files and programs", "B. Computer hardware", "C. Internet websites", "D. Paper documents"]', 'A', 'Desktop icons are graphical representations of files, folders, and programs that can be opened by clicking on them.', 'easy', 1, 19),
('q_bece_ict_2024_020', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'To save a document using the keyboard, you press:', 'multiple_choice', '["A. Ctrl + P", "B. Ctrl + S", "C. Ctrl + C", "D. Ctrl + V"]', 'B', 'Ctrl + S is the keyboard shortcut for saving a document. Ctrl + P prints, Ctrl + C copies, and Ctrl + V pastes.', 'easy', 1, 20),

-- Internet and Networks (Questions 21-30)
('q_bece_ict_2024_021', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'WWW stands for:', 'multiple_choice', '["A. World Wide Web", "B. World Web Wide", "C. Wide World Web", "D. Web Wide World"]', 'A', 'WWW stands for World Wide Web, which is a system of interlinked hypertext documents accessed via the internet.', 'easy', 1, 21),
('q_bece_ict_2024_022', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is a web browser?', 'multiple_choice', '["A. Windows", "B. Google Chrome", "C. Microsoft Word", "D. Photoshop"]', 'B', 'Google Chrome is a web browser used to access and navigate the internet. Windows is an OS, Word and Photoshop are applications.', 'easy', 1, 22),
('q_bece_ict_2024_023', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'An email address must contain the symbol:', 'multiple_choice', '["A. #", "B. @", "C. &", "D. $"]', 'B', 'All email addresses must contain the @ symbol, which separates the username from the domain name (e.g., user@domain.com).', 'easy', 1, 23),
('q_bece_ict_2024_024', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'A group of computers connected together to share resources is called:', 'multiple_choice', '["A. Internet", "B. Network", "C. Server", "D. Database"]', 'B', 'A network is a group of computers and devices connected together to share resources, data, and communicate with each other.', 'easy', 1, 24),
('q_bece_ict_2024_025', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'What does URL stand for?', 'multiple_choice', '["A. Uniform Resource Locator", "B. Universal Resource Locator", "C. Uniform Resource Link", "D. Universal Resource Link"]', 'A', 'URL stands for Uniform Resource Locator. It is the address of a webpage or resource on the internet.', 'medium', 1, 25),
('q_bece_ict_2024_026', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'A search engine is used to:', 'multiple_choice', '["A. Send emails", "B. Create documents", "C. Find information on the internet", "D. Play videos"]', 'C', 'A search engine like Google or Bing is used to find information, websites, images, and other content on the internet.', 'easy', 1, 26),
('q_bece_ict_2024_027', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is NOT a search engine?', 'multiple_choice', '["A. Google", "B. Yahoo", "C. Facebook", "D. Bing"]', 'C', 'Facebook is a social networking site, not a search engine. Google, Yahoo, and Bing are all search engines.', 'easy', 1, 27),
('q_bece_ict_2024_028', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'The abbreviation "http" stands for:', 'multiple_choice', '["A. Hyper Text Transfer Protocol", "B. High Text Transfer Protocol", "C. Hyper Text Transport Protocol", "D. High Text Transport Protocol"]', 'A', 'HTTP stands for Hyper Text Transfer Protocol, which is the foundation of data communication on the World Wide Web.', 'medium', 1, 28),
('q_bece_ict_2024_029', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'An ISP provides:', 'multiple_choice', '["A. Computer repairs", "B. Internet access", "C. Software development", "D. Hardware manufacturing"]', 'B', 'ISP stands for Internet Service Provider. It is a company that provides customers with internet access and related services.', 'medium', 1, 29),
('q_bece_ict_2024_030', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Wi-Fi is a technology used for:', 'multiple_choice', '["A. Printing documents", "B. Wireless internet connection", "C. Scanning images", "D. Recording audio"]', 'B', 'Wi-Fi is a wireless technology that allows devices to connect to the internet without physical cables.', 'easy', 1, 30),

-- Computer Safety and Ethics (Questions 31-40)
('q_bece_ict_2024_031', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'A computer virus is:', 'multiple_choice', '["A. A hardware problem", "B. A beneficial program", "C. A harmful program", "D. A type of browser"]', 'C', 'A computer virus is a harmful program designed to damage, disrupt, or gain unauthorized access to computer systems.', 'easy', 1, 31),
('q_bece_ict_2024_032', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Software used to protect computers from viruses is called:', 'multiple_choice', '["A. Malware", "B. Antivirus", "C. Shareware", "D. Freeware"]', 'B', 'Antivirus software is designed to detect, prevent, and remove malicious software including viruses, worms, and trojans.', 'easy', 1, 32),
('q_bece_ict_2024_033', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'A password should be:', 'multiple_choice', '["A. Easy to guess", "B. Your name or birthday", "C. Strong and unique", "D. Shared with friends"]', 'C', 'A password should be strong and unique, combining letters, numbers, and symbols to protect your accounts from unauthorized access.', 'easy', 1, 33),
('q_bece_ict_2024_034', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Cyberbullying refers to:', 'multiple_choice', '["A. Playing online games", "B. Harassment using electronic means", "C. Sending emails", "D. Creating websites"]', 'B', 'Cyberbullying is the use of electronic communication to bully, harass, or intimidate someone, often repeatedly.', 'medium', 1, 34),
('q_bece_ict_2024_035', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is an example of cybercrime?', 'multiple_choice', '["A. Watching movies online", "B. Hacking into accounts", "C. Using social media", "D. Sending emails"]', 'B', 'Hacking into someone''s accounts without permission is a cybercrime. It involves unauthorized access to computer systems.', 'medium', 1, 35),
('q_bece_ict_2024_036', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Copyright protects:', 'multiple_choice', '["A. Computer hardware", "B. Original creative works", "C. Computer viruses", "D. Network cables"]', 'B', 'Copyright is a legal right that protects original creative works like books, music, software, and art from unauthorized use.', 'medium', 1, 36),
('q_bece_ict_2024_037', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Downloading and using software without paying for it is called:', 'multiple_choice', '["A. Software development", "B. Software piracy", "C. Software testing", "D. Software installation"]', 'B', 'Software piracy is the illegal copying, distribution, or use of copyrighted software without proper authorization or payment.', 'medium', 1, 37),
('q_bece_ict_2024_038', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'To avoid eye strain when using a computer, you should:', 'multiple_choice', '["A. Sit very close to the screen", "B. Take regular breaks", "C. Keep room lights off", "D. Stare at the screen continuously"]', 'B', 'Taking regular breaks (20-20-20 rule) helps prevent eye strain. Looking away from the screen every 20 minutes reduces stress on your eyes.', 'easy', 1, 38),
('q_bece_ict_2024_039', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Phishing is:', 'multiple_choice', '["A. A type of online game", "B. A method of catching fish", "C. A cyber attack to steal personal information", "D. A type of computer software"]', 'C', 'Phishing is a cyber attack where criminals pose as legitimate organizations to trick people into revealing personal information like passwords or credit card numbers.', 'hard', 1, 39),
('q_bece_ict_2024_040', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2024_1', 'Which of the following is good practice when using social media?', 'multiple_choice', '["A. Sharing your password with friends", "B. Posting your home address", "C. Keeping personal information private", "D. Accepting all friend requests"]', 'C', 'Keeping personal information private on social media protects you from identity theft, cyberstalking, and other online threats.', 'easy', 1, 40),

-- BECE ICT Questions - 2023 (40 questions)
-- Computer Basics (Questions 1-10)
('q_bece_ict_2023_001', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The physical parts of a computer system are called:', 'multiple_choice', '["A. Software", "B. Hardware", "C. Firmware", "D. Malware"]', 'B', 'Hardware refers to the physical components of a computer that you can touch, such as the monitor, keyboard, mouse, and CPU.', 'easy', 1, 1),
('q_bece_ict_2023_002', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which component stores data permanently even when the computer is turned off?', 'multiple_choice', '["A. RAM", "B. Cache", "C. Hard disk", "D. Processor"]', 'C', 'The hard disk (HDD or SSD) is non-volatile storage that retains data permanently even when the computer is powered off.', 'medium', 1, 2),
('q_bece_ict_2023_003', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'ROM stands for:', 'multiple_choice', '["A. Random Only Memory", "B. Read Only Memory", "C. Read Open Memory", "D. Run Only Memory"]', 'B', 'ROM stands for Read Only Memory. It contains permanent instructions that are built into the computer and cannot be modified.', 'easy', 1, 3),
('q_bece_ict_2023_004', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A mouse is classified as:', 'multiple_choice', '["A. Output device", "B. Input device", "C. Processing device", "D. Storage device"]', 'B', 'A mouse is an input device that allows users to point, click, and interact with the computer''s graphical user interface.', 'easy', 1, 4),
('q_bece_ict_2023_005', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is a pointing device?', 'multiple_choice', '["A. Monitor", "B. Speaker", "C. Trackpad", "D. Printer"]', 'C', 'A trackpad is a pointing device that allows users to control the cursor by moving their finger across a touch-sensitive surface.', 'easy', 1, 5),
('q_bece_ict_2023_006', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'One kilobyte (KB) is equal to:', 'multiple_choice', '["A. 1000 bytes", "B. 1024 bytes", "C. 100 bytes", "D. 10000 bytes"]', 'B', 'One kilobyte equals 1024 bytes. This is because computers work in binary (base 2), and 2^10 = 1024.', 'medium', 1, 6),
('q_bece_ict_2023_007', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The arrangement of keys on a keyboard is called:', 'multiple_choice', '["A. Mouse pad", "B. Keypad", "C. Keyboard layout", "D. Monitor"]', 'C', 'The arrangement of keys on a keyboard is called the keyboard layout. The most common layout is QWERTY.', 'easy', 1, 7),
('q_bece_ict_2023_008', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'USB stands for:', 'multiple_choice', '["A. Universal Serial Bus", "B. United Serial Bus", "C. Universal System Bus", "D. United System Bus"]', 'A', 'USB stands for Universal Serial Bus. It is a standard for connecting devices to computers for data transfer and charging.', 'medium', 1, 8),
('q_bece_ict_2023_009', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A scanner is used to:', 'multiple_choice', '["A. Print documents", "B. Convert physical documents to digital format", "C. Connect to the internet", "D. Store files"]', 'B', 'A scanner is an input device that captures images of physical documents or photos and converts them into digital format.', 'easy', 1, 9),
('q_bece_ict_2023_010', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is a storage device?', 'multiple_choice', '["A. Webcam", "B. USB flash drive", "C. Microphone", "D. Speaker"]', 'B', 'A USB flash drive is a portable storage device used to store and transfer digital files between computers.', 'easy', 1, 10),

-- Software Applications (Questions 11-20)
('q_bece_ict_2023_011', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The bar at the bottom of the Windows desktop is called:', 'multiple_choice', '["A. Menu bar", "B. Taskbar", "C. Title bar", "D. Status bar"]', 'B', 'The taskbar is the bar at the bottom of the Windows desktop that contains the Start button, running programs, and system tray.', 'easy', 1, 11),
('q_bece_ict_2023_012', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'To copy text using keyboard shortcuts, you press:', 'multiple_choice', '["A. Ctrl + X", "B. Ctrl + V", "C. Ctrl + C", "D. Ctrl + Z"]', 'C', 'Ctrl + C is the keyboard shortcut for copying text or objects. Ctrl + X cuts, Ctrl + V pastes, and Ctrl + Z undoes.', 'easy', 1, 12),
('q_bece_ict_2023_013', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which software would you use to create slides for a presentation?', 'multiple_choice', '["A. Microsoft Word", "B. Microsoft Excel", "C. Microsoft PowerPoint", "D. Microsoft Access"]', 'C', 'Microsoft PowerPoint is designed specifically for creating presentations with slides, animations, and transitions.', 'easy', 1, 13),
('q_bece_ict_2023_014', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'In Microsoft Word, the blinking vertical line where you type is called:', 'multiple_choice', '["A. Mouse pointer", "B. Cursor", "C. Icon", "D. Button"]', 'B', 'The cursor (or insertion point) is the blinking vertical line that indicates where text will be inserted when you type.', 'easy', 1, 14),
('q_bece_ict_2023_015', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A folder is used to:', 'multiple_choice', '["A. Delete files", "B. Organize files", "C. Print documents", "D. Connect to internet"]', 'B', 'Folders are used to organize and store files in a hierarchical structure, making it easier to locate and manage documents.', 'easy', 1, 15),
('q_bece_ict_2023_016', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'To undo the last action, you press:', 'multiple_choice', '["A. Ctrl + Y", "B. Ctrl + Z", "C. Ctrl + U", "D. Ctrl + A"]', 'B', 'Ctrl + Z is the universal keyboard shortcut for undoing the last action. Ctrl + Y is used to redo.', 'easy', 1, 16),
('q_bece_ict_2023_017', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The file extension ".exe" indicates:', 'multiple_choice', '["A. An image file", "B. A text file", "C. An executable program", "D. A music file"]', 'C', 'The .exe extension indicates an executable file - a program that can be run on Windows operating systems.', 'medium', 1, 17),
('q_bece_ict_2023_018', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is NOT an operating system?', 'multiple_choice', '["A. Windows", "B. Linux", "C. Android", "D. Microsoft Office"]', 'D', 'Microsoft Office is a suite of productivity applications, not an operating system. Windows, Linux, and Android are all operating systems.', 'medium', 1, 18),
('q_bece_ict_2023_019', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'To print a document, you press:', 'multiple_choice', '["A. Ctrl + S", "B. Ctrl + P", "C. Ctrl + O", "D. Ctrl + N"]', 'B', 'Ctrl + P is the keyboard shortcut for printing a document. A print dialog box will appear to select printer settings.', 'easy', 1, 19),
('q_bece_ict_2023_020', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The Recycle Bin is used to:', 'multiple_choice', '["A. Permanently delete files", "B. Store deleted files temporarily", "C. Organize files", "D. Create new folders"]', 'B', 'The Recycle Bin temporarily stores deleted files, allowing users to restore them if needed or permanently delete them.', 'easy', 1, 20),

-- Internet and Communication (Questions 21-30)
('q_bece_ict_2023_021', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The internet is:', 'multiple_choice', '["A. A single computer", "B. A local network", "C. A global network of networks", "D. A software program"]', 'C', 'The internet is a global network of interconnected networks that allows computers worldwide to communicate and share information.', 'easy', 1, 21),
('q_bece_ict_2023_022', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'E-mail stands for:', 'multiple_choice', '["A. Electric mail", "B. Electronic mail", "C. Easy mail", "D. Express mail"]', 'B', 'E-mail stands for Electronic mail, which is a method of sending and receiving digital messages over the internet.', 'easy', 1, 22),
('q_bece_ict_2023_023', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is a valid email address format?', 'multiple_choice', '["A. john.gmail.com", "B. john@gmail.com", "C. john@gmail", "D. @gmail.com"]', 'B', 'A valid email address has the format username@domain.extension (e.g., john@gmail.com).', 'easy', 1, 23),
('q_bece_ict_2023_024', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A website is identified by its:', 'multiple_choice', '["A. Password", "B. URL", "C. Email", "D. Username"]', 'B', 'A website is identified by its URL (Uniform Resource Locator), which is the web address that specifies its location on the internet.', 'easy', 1, 24),
('q_bece_ict_2023_025', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'LAN stands for:', 'multiple_choice', '["A. Large Area Network", "B. Local Access Network", "C. Local Area Network", "D. Long Area Network"]', 'C', 'LAN stands for Local Area Network - a network that connects computers in a limited area such as a home, school, or office.', 'medium', 1, 25),
('q_bece_ict_2023_026', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'To refresh a web page, you press:', 'multiple_choice', '["A. F1", "B. F5", "C. F10", "D. F12"]', 'B', 'F5 is the keyboard shortcut to refresh or reload a web page in most browsers. It fetches the latest version from the server.', 'easy', 1, 26),
('q_bece_ict_2023_027', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A bookmark in a web browser is used to:', 'multiple_choice', '["A. Delete websites", "B. Save website addresses for quick access", "C. Block websites", "D. Download files"]', 'B', 'Bookmarks (or favorites) save website addresses so you can quickly return to them without typing the URL again.', 'easy', 1, 27),
('q_bece_ict_2023_028', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The address bar in a browser is used to:', 'multiple_choice', '["A. Search for files on your computer", "B. Type website addresses", "C. Send emails", "D. Download software"]', 'B', 'The address bar is where you type the URL of a website you want to visit. It also displays the current page''s address.', 'easy', 1, 28),
('q_bece_ict_2023_029', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'HTML stands for:', 'multiple_choice', '["A. Hyper Text Markup Language", "B. High Text Markup Language", "C. Hyper Transfer Markup Language", "D. High Transfer Markup Language"]', 'A', 'HTML stands for Hyper Text Markup Language. It is the standard language used to create and structure web pages.', 'medium', 1, 29),
('q_bece_ict_2023_030', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'An attachment in an email is:', 'multiple_choice', '["A. The email address", "B. A file sent with the email", "C. The subject line", "D. The email signature"]', 'B', 'An attachment is a file (document, image, video, etc.) that is sent along with an email message.', 'easy', 1, 30),

-- Safety, Ethics, and Emerging Technologies (Questions 31-40)
('q_bece_ict_2023_031', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Spam refers to:', 'multiple_choice', '["A. Important emails", "B. Unwanted emails sent in bulk", "C. Personal emails", "D. Work emails"]', 'B', 'Spam refers to unsolicited, unwanted emails that are sent in bulk, often for advertising or malicious purposes.', 'easy', 1, 31),
('q_bece_ict_2023_032', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A firewall is used to:', 'multiple_choice', '["A. Cool down the computer", "B. Protect the computer from unauthorized access", "C. Speed up the internet", "D. Store files"]', 'B', 'A firewall is a security system that monitors and controls network traffic, protecting computers from unauthorized access and cyber threats.', 'medium', 1, 32),
('q_bece_ict_2023_033', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is a social media platform?', 'multiple_choice', '["A. Microsoft Word", "B. Facebook", "C. Google Docs", "D. Adobe Photoshop"]', 'B', 'Facebook is a social media platform where users can connect, share content, and communicate with others online.', 'easy', 1, 33),
('q_bece_ict_2023_034', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Plagiarism means:', 'multiple_choice', '["A. Creating original content", "B. Copying someone else''s work without giving credit", "C. Sharing information online", "D. Using legal software"]', 'B', 'Plagiarism is the act of copying someone else''s work, ideas, or words and presenting them as your own without proper attribution.', 'medium', 1, 34),
('q_bece_ict_2023_035', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'A backup is:', 'multiple_choice', '["A. Deleting old files", "B. A copy of data stored separately", "C. Installing new software", "D. Updating the operating system"]', 'B', 'A backup is a copy of data stored in a separate location to protect against data loss from hardware failure, viruses, or accidental deletion.', 'easy', 1, 35),
('q_bece_ict_2023_036', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Ergonomics in computing involves:', 'multiple_choice', '["A. Designing comfortable work environments", "B. Installing software", "C. Connecting to the internet", "D. Creating websites"]', 'A', 'Ergonomics involves designing work environments and equipment to be comfortable and safe, reducing strain and injury risks.', 'medium', 1, 36),
('q_bece_ict_2023_037', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Cloud computing allows users to:', 'multiple_choice', '["A. Only work offline", "B. Store and access data over the internet", "C. Repair computer hardware", "D. Create new hardware"]', 'B', 'Cloud computing allows users to store, access, and process data over the internet instead of on local computers or servers.', 'medium', 1, 37),
('q_bece_ict_2023_038', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'The term "netiquette" refers to:', 'multiple_choice', '["A. Internet speed", "B. Network hardware", "C. Online etiquette and behavior", "D. Web design"]', 'C', 'Netiquette (network etiquette) refers to the proper, polite, and respectful behavior expected when communicating online.', 'medium', 1, 38),
('q_bece_ict_2023_039', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'Which of the following is a good practice for password security?', 'multiple_choice', '["A. Using the same password for all accounts", "B. Writing passwords on sticky notes", "C. Using different passwords for different accounts", "D. Sharing passwords with classmates"]', 'C', 'Using different passwords for different accounts improves security. If one account is compromised, others remain protected.', 'easy', 1, 39),
('q_bece_ict_2023_040', 'subj_bece_ict', 'exam_bece', 'paper_bece_1', 'pp_bece_ict_2023_1', 'To protect your eyes when using a computer, you should:', 'multiple_choice', '["A. Sit as close as possible to the screen", "B. Use a screen that is too bright", "C. Position the monitor at eye level and reduce glare", "D. Never take breaks"]', 'C', 'Positioning the monitor at eye level, reducing glare, and maintaining proper distance helps protect your eyes from strain and fatigue.', 'easy', 1, 40);
